  // Prevents parser errors with transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animations - Timings
  const headerSlide = spring({ frame, fps, config: { damping: 15 } });
  const cardSpring = spring({ frame: frame - 15, fps, config: { damping: 14, mass: 0.8 } });
  
  const metricsOpacity = interpolate(frame, [30, 45], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const metricsY = interpolate(spring({ frame: frame - 30, fps }), [0, 1], [40, 0]);

  const animatedSpend = interpolate(frame, [40, 70], [0, spendAmount], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const animatedPurchases = interpolate(frame, [45, 75], [0, purchases], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const animatedRoas = interpolate(frame, [50, 90], [0, roasValue], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const chartClipProgress = spring({ frame: frame - 70, fps, config: { damping: 20 } });
  const chartClipWidth = interpolate(chartClipProgress, [0, 1], [0, 100]);

